import zipfile
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def q(tag):
    return '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}' + tag

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("archive members:", names)

    # shared strings
    sst = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall(q('si')):
            text = ''.join(t.text or '' for t in si.iter(q('t')))
            sst.append(text)

    # workbook sheets and rels
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels:
        rel_map[rel.get('Id')] = rel.get('Target')

    print("\n--- SHEETS ---")
    sheet_files = []
    for sheet in wb.iter(q('sheet')):
        rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = rel_map.get(rid, '')
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        sheet_files.append((sheet.get('name'), target))
        print(f"sheet '{sheet.get('name')}' -> {target}")

    # styles: map style index -> numFmtId
    styles_root = ET.fromstring(z.read('xl/styles.xml'))
    numfmt_map = {}
    cellxf = styles_root.find(q('cellXfs'))
    cellxfs = cellxf.findall(q('xf')) if cellxf is not None else []

    print("\n--- CELLS ---")
    for sheet_name, target in sheet_files:
        if target not in names:
            print(f"WARNING: {target} not in archive")
            continue
        ws = ET.fromstring(z.read(target))
        print(f"\n=== Sheet: {sheet_name} ===")
        for row in ws.iter(q('row')):
            for c in row.findall(q('c')):
                ref = c.get('r')
                t = c.get('t')
                v = c.find(q('v'))
                isel = c.find(q('is'))
                val = None
                if t == 's' and v is not None:
                    val = sst[int(v.text)]
                elif t == 'inlineStr' and isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter(q('t')))
                elif v is not None:
                    val = v.text
                if val is not None:
                    print(f"{ref}: {repr(val)}")

