def q(tag):
    return '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}' + tag

RID = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'

def col_letter(ref):
    return ''.join(ch for ch in ref if ch.isalpha())

def row_num(ref):
    return int(''.join(ch for ch in ref if ch.isdigit()))

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    ws = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    expenses = []
    for row in ws.iter(q('row')):
        for c in row.findall(q('c')):
            ref = c.get('r')
            v = c.find(q('v'))
            if v is None:
                continue
            if col_letter(ref) == 'C' and 11 <= row_num(ref) <= 22:
                expenses.append((ref, int(v.text)))
    print("Expense cells found:")
    for ref, val in expenses:
        print(f"  {ref}: {val}")
    print("TOTAL EXPENSES:", sum(val for _, val in expenses))

